-- Free, provider-independent in-app delivery receipt for verified members.
-- One idempotent self-check per owner per UTC day. No provider messages or
-- administrator rights can be generated by this function.
create or replace function public.ifund_notification_delivery_selfcheck()
returns table (notification_id uuid, delivered_at timestamptz, already_exists boolean)
language plpgsql volatile security definer
set search_path = ''
set row_security = 'off'
set lock_timeout = '3s'
as $$
declare
  v_owner uuid := auth.uid();
  v_key text;
  v_id uuid;
  v_at timestamptz;
  v_existing boolean := false;
begin
  if v_owner is null
    or not coalesce(public.ifund_current_account_is_active(), false)
    or not coalesce(public.ifund_current_user_has_current_terms(), false)
    or not exists (
      select 1 from auth.users u
      where u.id = v_owner and u.is_anonymous is false
        and u.email_confirmed_at is not null
    )
  then
    raise exception 'A verified member account with current terms is required'
      using errcode = '42501';
  end if;

  v_key := 'notification:self-check:v1:' || v_owner::text || ':'
    || ((pg_catalog.clock_timestamp() at time zone 'UTC')::date)::text;

  insert into public.ifund_notifications
    (owner_id, title, body, type, link, canonical_operation_id)
  values (
    v_owner,
    'Your iFund inbox is connected',
    'This test notice was saved in your private iFund inbox. No email, SMS, social message, payment or public post was sent.',
    'system',
    '/notifications',
    v_key
  )
  on conflict (canonical_operation_id)
    where canonical_operation_id is not null do nothing
  returning id, created_at into v_id, v_at;

  if v_id is null then
    v_existing := true;
    select n.id, n.created_at into v_id, v_at
      from public.ifund_notifications n
      where n.owner_id = v_owner
        and n.canonical_operation_id = v_key;
  end if;

  if v_id is null or v_at is null then
    raise exception 'Notification could not be confirmed'
      using errcode = 'P0001';
  end if;

  return query select v_id, v_at, v_existing;
end;
$$;

revoke all on function public.ifund_notification_delivery_selfcheck()
  from public, anon;
grant execute on function public.ifund_notification_delivery_selfcheck()
  to authenticated;
